 <div class="game-over" id="gameOver"><div><div class="eyebrow" style="justify-content:center">OPERATION COMPLETE</div><h2>MISSION ENDED</h2><p id="finalScore"></p><button class="again" id="returnMenu">RETURN TO COMMAND</button></div></div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.165.0/build/three.module.js';
+const mount=document.querySelector('#world');
+const scene=new THREE.Scene();scene.background=new THREE.Color(0x9cad9e);scene.fog=new THREE.FogExp2(0x93a394,.0025);
