+scene.add(new THREE.HemisphereLight(0xc8d7ce,0x263a2d,2.1));const sun=new THREE.DirectionalLight(0xffe6bc,3.2);sun.position.set(-90,140,45);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-140;sun.shadow.camera.right=140;sun.shadow.camera.top=140;sun.shadow.camera.bottom=-140;scene.add(sun);
+const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
+const grass=mat(0x455b3b),sand=mat(0xc6b68d),water=mat(0x315e61,.32,.28),roadMat=mat(0x393e39),roofMat=mat(0x50564c),trunkMat=mat(0x493d2d),leafMats=[mat(0x344c36),mat(0x435f3f),mat(0x536d46),mat(0x2d4438)],buildingMats=[mat(0x857d67),mat(0x62685d),mat(0x9b8c6e)];
+const H=(x,z)=>{let r=Math.sqrt((x/228)**2+(z/228)**2),edge=Math.max(0,1-r);let hills=(Math.sin(x*.038+z*.014)*3.3+Math.sin(z*.067-x*.024)*2.1+Math.cos(x*.019-z*.029)*4.4);let ridge=14*Math.exp(-((x-55)**2/3100+(z+35)**2/4200))+9*Math.exp(-((x+87)**2/2100+(z-35)**2/3600));return Math.max(-1,edge*edge*(9+hills+ridge)-2.5)};
+const groundGeo=new THREE.PlaneGeometry(520,520,180,180);groundGeo.rotateX(-Math.PI/2);const pos=groundGeo.attributes.position,cols=[];for(let i=0;i<pos.count;i++){let x=pos.getX(i),z=pos.getZ(i),h=H(x,z);pos.setY(i,h);let c=new THREE.Color(h<0?0x766f58:h<2?0xa2936a:h>14?0x686b55:h>7?0x58694a:0x465b3c);let v=.92+Math.random()*.15;c.multiplyScalar(v);cols.push(c.r,c.g,c.b)}groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(cols,3));groundGeo.computeVertexNormals();let ground=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);
+const sea=new THREE.Mesh(new THREE.PlaneGeometry(1500,1500),water);sea.rotation.x=-Math.PI/2;sea.position.y=-1.1;scene.add(sea);
+// Coastal headlands and distant volcanic silhouettes
+for(let i=0;i<9;i++){let a=i/9*Math.PI*2,r=235+Math.random()*35,x=Math.cos(a)*r,z=Math.sin(a)*r;let m=new THREE.Mesh(new THREE.ConeGeometry(32+Math.random()*28,55+Math.random()*65,7),mat(i%2?0x526158:0x667065));m.position.set(x,18,z);m.rotation.z=(Math.random()-.5)*.24;scene.add(m)}
+// Dense tropical canopy, instanced to preserve performance
+const trunkGeo=new THREE.CylinderGeometry(.13,.25,3.7,5),crownGeo=new THREE.ConeGeometry(2.15,5.6,6);const treeN=1350, trunks=new THREE.InstancedMesh(trunkGeo,trunkMat,treeN),canopy=new THREE.InstancedMesh(crownGeo,leafMats[0],treeN);const dummy=new THREE.Object3D();let ti=0;while(ti<treeN){let x=(Math.random()-.5)*410,z=(Math.random()-.5)*410,r=Math.sqrt(x*x+z*z);if(r<27||r>211)continue;if(Math.abs(x)<20&&z>42&&z<105)continue;if(x>32&&x<94&&z>-76&&z<-28)continue;let y=H(x,z);dummy.position.set(x,y+1.6,z);dummy.scale.setScalar(.68+Math.random()*.85);dummy.rotation.y=Math.random()*6.28;dummy.updateMatrix();trunks.setMatrixAt(ti,dummy.matrix);dummy.position.y=y+4;dummy.scale.setScalar(.72+Math.random()*.78);dummy.rotation.y=Math.random()*6.28;dummy.updateMatrix();canopy.setMatrixAt(ti,dummy.matrix);canopy.setColorAt(ti,new THREE.Color(leafMats[Math.floor(Math.random()*leafMats.length)].color));ti++}trunks.castShadow=true;canopy.castShadow=true;scene.add(trunks,canopy);
+// Roads wind through villages and out to the airfield
+function road(points,width=4){let curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,H(x,z)+.13,z)));let mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,Math.max(30,points.length*16),width/2,5,false),roadMat);mesh.scale.y=.18;scene.add(mesh)}
+road([[-205,68],[-125,42],[-70,58],[-20,78],[30,64],[94,20],[176,-6]],4.8);road([[-35,170],[-25,122],[-3,85],[8,43],[45,3],[75,-50],[92,-143]],4.4);road([[-170,-58],[-112,-42],[-75,-8],[-34,2],[5,-9],[54,-35],[116,-72]],3.5);
+// Buildings and military compounds
+function building(x,z,w,d,h,kind=0){let y=H(x,z);let g=new THREE.Group();let body=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),buildingMats[kind%3]);body.position.y=h/2;body.castShadow=true;body.receiveShadow=true;g.add(body);let roof=new THREE.Mesh(new THREE.BoxGeometry(w+1,.6,d+1),roofMat);roof.position.y=h+.3;roof.castShadow=true;g.add(roof);let door=new THREE.Mesh(new THREE.BoxGeometry(Math.min(1.3,w*.19),h*.46,.18),mat(0x292c25));door.position.set(0,h*.23,d/2+.1);g.add(door);for(let wx=-1;wx<=1;wx+=2){if(w>8){let win=new THREE.Mesh(new THREE.BoxGeometry(1.2,1.05,.15),mat(0x293d3b,.3));win.position.set(wx*w*.28,h*.57,d/2+.1);g.add(win)}}g.position.set(x,y,z);scene.add(g);return g}
+// Blackwater village
+for(const [x,z,w,d,h] of [[-48,82,12,10,5],[-31,93,9,10,4],[-60,105,14,9,5],[-23,114,10,8,5],[-53,129,12,9,4],[-8,122,10,10,5],[-74,78,9,8,4]])building(x,z,w,d,h,Math.floor(Math.random()*3));
+// Kestrel airfield: runway, hangars and control tower
+let runway=new THREE.Mesh(new THREE.BoxGeometry(23,.3,110),mat(0x444a46));runway.position.set(65,H(65,0)+.16,0);runway.rotation.y=.27;scene.add(runway);for(let i=-5;i<=5;i++){let stripe=new THREE.Mesh(new THREE.BoxGeometry(.4,.1,4),mat(0xd0cbb2));stripe.position.set(65,H(65,0)+.36,i*9);stripe.rotation.y=.27;scene.add(stripe)}building(91,-55,23,17,8,1);building(104,-29,26,17,9,1);building(48,-69,12,12,17,2);building(45,-51,12,12,17,2);for(let x=112;x<141;x+=12)building(x,-100+(x%2)*14,10,9,5,0);
+// Bunker entrance at the ridge
+building(-107,-25,19,14,6,1);let bunker=building(-107,-25,13,9,4,0);bunker.position.y-=1.5;
+// Silvery tropical waterway ribbon
+const riverMat=mat(0x477f83,.25,.16);let river=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([[-130,0,155],[-90,0,125],[-65,0,75],[-38,0,34],[-5,0,-12],[25,0,-72],[55,0,-134]].map(v=>new THREE.Vector3(v[0],H(v[0],v[2])+.06,v[2]))),100,2.3,8,false),riverMat);river.scale.y=.18;scene.add(river);
+// Vegetation along the coast
+for(let i=0;i<55;i++){let a=Math.random()*Math.PI*2,r=145+Math.random()*62,x=Math.cos(a)*r,z=Math.sin(a)*r;if(r>211)continue;let palm=new THREE.Group(),y=H(x,z);let trunk=new THREE.Mesh(new THREE.CylinderGeometry(.17,.28,7,5),trunkMat);trunk.position.y=3.5;palm.add(trunk);for(let l=0;l<7;l++){let f=new THREE.Mesh(new THREE.ConeGeometry(.38,5.5,4),leafMats[l%4]);f.position.y=7;f.rotation.z=Math.PI*.64;f.rotation.y=l*Math.PI/3.5;f.scale.set(1,.48,1);palm.add(f)}palm.position.set(x,y,z);palm.rotation.y=Math.random()*6;scene.add(palm)}
+// Storm-lit cloud veil
+const cloudMat=new THREE.MeshBasicMaterial({color:0xc2cec3,transparent:true,opacity:.11,depthWrite:false});for(let i=0;i<34;i++){let cl=new THREE.Mesh(new THREE.SphereGeometry(12+Math.random()*17,7,5),cloudMat);cl.scale.set(1.9,.18,1);cl.position.set((Math.random()-.5)*520,55+Math.random()*20,(Math.random()-.5)*520);scene.add(cl)}
+// Weapon view model
+const gun=new THREE.Group();const gunMat=mat(0x303732,.34,.68),darkMat=mat(0x141a17,.4,.35),accentMat=mat(0x7d896f,.52,.45);function gunbox(g,m,p,s){let o=new THREE.Mesh(new THREE.BoxGeometry(...s),m);o.position.set(...p);g.add(o);return o}gunbox(gun,gunMat,[0,0,0],[.15,.18,.78]);gunbox(gun,darkMat,[0,-.01,-.44],[.075,.075,.68]);gunbox(gun,gunMat,[0,-.13,.14],[.11,.25,.22]);gunbox(gun,darkMat,[0,-.18,.34],[.12,.1,.35]);gunbox(gun,accentMat,[0,.12,-.07],[.1,.07,.29]);gun.position.set(.34,-.3,-.62);camera.add(gun);scene.add(camera);
+// Soldiers: player counts remain exactly 25 per force, with 49 simulated operators
+const blueMat=mat(0x4f96b3),redMat=mat(0xb95242),gearMat=mat(0x333a32),skinMat=mat(0xb99674),enemyGlow=mat(0xd06a55,.55);const cyl=new THREE.CapsuleGeometry(.44,1.12,3,7),headGeo=new THREE.SphereGeometry(.28,8,7),helmetGeo=new THREE.SphereGeometry(.32,8,6);const actors=[];
+function makeSoldier(team,x,z,index){let group=new THREE.Group(),shirt=new THREE.Mesh(cyl,team==='blue'?blueMat:redMat);shirt.position.y=1.04;shirt.castShadow=true;group.add(shirt);let head=new THREE.Mesh(headGeo,skinMat);head.position.y=1.9;group.add(head);let helmet=new THREE.Mesh(helmetGeo,team==='blue'?mat(0x314c54):mat(0x53342e));helmet.scale.y=.58;helmet.position.y=2.08;group.add(helmet);let pack=new THREE.Mesh(new THREE.BoxGeometry(.52,.72,.28),gearMat);pack.position.set(0,1.1,.48);group.add(pack);let rifle=new THREE.Mesh(new THREE.BoxGeometry(.09,.09,.75),darkMat);rifle.position.set(.36,1.22,-.27);group.add(rifle);let marker=new THREE.Mesh(new THREE.ConeGeometry(.12,.22,4),team==='blue'?mat(0x69c7ee):enemyGlow);marker.position.y=2.45;group.add(marker);group.position.set(x,H(x,z),z);scene.add(group);let a={group,team,index,hp:100,alive:true,phase:Math.random()*10,origin:new THREE.Vector3(x,0,z),speed:.9+Math.random()*.5,fire:Math.random()*3};actors.push(a);return a}
+for(let i=0;i<24;i++){let a=i/24*Math.PI*2,r=16+Math.random()*48,x=Math.cos(a)*r,z=63+Math.sin(a)*r;if(Math.abs(x)<27&&z<52)z+=26;makeSoldier('blue',x,z,i)}for(let i=0;i<25;i++){let a=i/25*Math.PI*2,r=24+Math.random()*68,x=62+Math.cos(a)*r,z=-28+Math.sin(a)*r;makeSoldier('red',x,z,i)}
+// Flag and objective markers
+function flag(x,z,color){let pole=new THREE.Mesh(new THREE.CylinderGeometry(.075,.1,5,6),mat(0xd0d0b8));pole.position.set(x,H(x,z)+2.5,z);scene.add(pole);let cloth=new THREE.Mesh(new THREE.PlaneGeometry(2.1,1.1),mat(color,.7));cloth.position.set(x+1,H(x,z)+4.35,z);scene.add(cloth);return cloth}flag(0,63,0x68bde4);flag(66,-28,0xe66b58);
+// Combat state & input
+const keys={},raycaster=new THREE.Raycaster();let yaw=0,pitch=0,playing=false,ammo=30,reserve=180,health=100,blueScore=0,redScore=0,kills=0,selectedMode='TDM',lastFire=0,enemyClock=0,walkTime=0,locked=false;
+const start=document.querySelector('#startScreen'),hud=document.querySelector('#gameHud');function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.opacity=0,950)}
+function setMode(m){selectedMode=m;document.querySelectorAll('.mode').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));let labels={TDM:['TEAM DEATHMATCH','ELIMINATE HOSTILE OPERATORS'],CTF:['CAPTURE THE FLAG','SECURE THE ENEMY STANDARD'],DOM:['DOMINATION','CONTROL THE STRATEGIC POINTS']};document.querySelector('#hudMode').textContent=labels[m][0];document.querySelector('#objective').textContent=labels[m][1]}
+document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
+function deploy(){playing=true;start.classList.add('hidden-ui');hud.style.display='block';document.querySelector('#mobileControls').style.display=innerWidth<800?'block':'none';camera.position.set(0,H(0,46)+2.45,46);yaw=0;pitch=-.04;camera.rotation.set(pitch,yaw,0,'YXZ');document.body.requestPointerLock?.();toast('DEPLOYED — VANGUARD SECTOR');}
+document.querySelector('#deploy').onclick=deploy;document.querySelector('#returnMenu').onclick=()=>{document.querySelector('#gameOver').style.display='none';playing=false;start.classList.remove('hidden-ui');hud.style.display='none'};
+document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===document.body);document.addEventListener('mousemove',e=>{if(playing&&locked){yaw-=e.movementX*.0022;pitch-=e.movementY*.0019;pitch=Math.max(-1.25,Math.min(1.18,pitch));camera.rotation.set(pitch,yaw,0,'YXZ')}});
+document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&playing&&!locked){playing=false;hud.style.display='none';start.classList.remove('hidden-ui')}if(e.code==='KeyR')reload();if(e.code==='Space'&&playing&&onGround)velocityY=6.2});document.addEventListener('keyup',e=>keys[e.code]=false);
+document.addEventListener('mousedown',e=>{if(e.button===0&&playing){if(!locked)document.body.requestPointerLock?.();fire()}});document.addEventListener('mouseup',()=>{});
+let isFiring=false;document.addEventListener('pointerdown',e=>{if(e.target===renderer.domElement&&playing)isFiring=true});document.addEventListener('pointerup',()=>isFiring=false);
+function reload(){if(ammo>=30||reserve<=0)return;toast('RELOADING');setTimeout(()=>{let n=Math.min(30-ammo,reserve);ammo+=n;reserve-=n;document.querySelector('#ammo').textContent=ammo;document.querySelector('#reserve').textContent=reserve},850)}
+function fire(){let now=performance.now();if(now-lastFire<115)return;lastFire=now;if(ammo<=0){toast('MAGAZINE EMPTY — R TO RELOAD');return}ammo--;document.querySelector('#ammo').textContent=ammo;gun.position.x=.34+(Math.random()-.5)*.016;gun.position.z=-.62+.07;setTimeout(()=>gun.position.z=-.62,55);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);let candidates=actors.filter(a=>a.alive&&a.team==='red');let best=null,bestDist=Infinity;for(let a of candidates){let p=a.group.position.clone();p.y+=1.2;let d=p.clone().sub(camera.position),along=d.dot(raycaster.ray.direction);if(along<0||along>115)continue;let near=raycaster.ray.origin.clone().addScaledVector(raycaster.ray.direction,along);let miss=near.distanceTo(p);if(miss<1.6&&miss<bestDist){best=a;bestDist=miss}}if(best){best.hp-=34;if(best.hp<=0){best.alive=false;best.group.visible=false;blueScore++;kills++;document.querySelector('#blueScore').textContent=blueScore;toast('HOSTILE DOWN  +100 XP');setTimeout(()=>respawn(best),3800)}else toast('HIT CONFIRMED')} }
+function respawn(a){let x=65+(Math.random()-.5)*110,z=-28+(Math.random()-.5)*105;a.hp=100;a.group.position.set(x,H(x,z),z);a.alive=true;a.group.visible=true}
+let velocityY=0,onGround=true;function damage(n){health=Math.max(0,health-n);document.querySelector('#health').textContent=health;document.querySelector('#healthFill').style.width=health+'%';if(health<=0){health=100;camera.position.set(0,H(0,46)+2.45,46);toast('SQUAD MEDIC — BACK IN ACTION')}}
+// Touch controls
+let touchMove={x:0,y:0},touchLook=null;const stick=document.querySelector('#stick');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);touchMove.startX=e.clientX;touchMove.startY=e.clientY});stick.addEventListener('pointermove',e=>{if(e.buttons){touchMove.x=Math.max(-1,Math.min(1,(e.clientX-touchMove.startX)/42));touchMove.y=Math.max(-1,Math.min(1,(e.clientY-touchMove.startY)/42))}});stick.addEventListener('pointerup',()=>touchMove={x:0,y:0});let lookZone=document.querySelector('#lookZone');lookZone.addEventListener('pointerdown',e=>{touchLook={x:e.clientX,y:e.clientY};lookZone.setPointerCapture(e.pointerId)});lookZone.addEventListener('pointermove',e=>{if(touchLook){yaw-=(e.clientX-touchLook.x)*.006;pitch=Math.max(-1.25,Math.min(1.18,pitch-(e.clientY-touchLook.y)*.005));camera.rotation.set(pitch,yaw,0,'YXZ');touchLook={x:e.clientX,y:e.clientY}}});lookZone.addEventListener('pointerup',()=>touchLook=null);document.querySelector('#fireTouch').onpointerdown=e=>{e.preventDefault();fire();isFiring=true};document.querySelector('#fireTouch').onpointerup=()=>isFiring=false;document.querySelector('#reloadTouch').onclick=reload;
+window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
+let clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.05),t=clock.elapsedTime;sun.position.x=-90+Math.sin(t*.025)*22;scene.fog.density=.0024+Math.sin(t*.04)*.00025;cloudMat.opacity=.095+Math.sin(t*.08)*.025;
+if(playing){if(isFiring&&locked&&performance.now()-lastFire>145)fire();let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-touchMove.y,r=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touchMove.x;let sp=(keys.ShiftLeft||keys.ShiftRight?12:keys.KeyC?3:7.2)*dt;if(f||r){let dx=(Math.sin(yaw)*f+Math.cos(yaw)*r),dz=(-Math.cos(yaw)*f+Math.sin(yaw)*r),len=Math.hypot(dx,dz)||1;camera.position.x+=dx/len*sp;camera.position.z+=dz/len*sp;walkTime+=dt*(keys.ShiftLeft?13:8);gun.position.y=-.3+Math.sin(walkTime)*.009}camera.position.x=THREE.MathUtils.clamp(camera.position.x,-205,205);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-205,205);if(camera.position.y>H(camera.position.x,camera.position.z)+2.45||!onGround){velocityY-=16*dt;camera.position.y+=velocityY*dt;if(camera.position.y<=H(camera.position.x,camera.position.z)+2.45){camera.position.y=H(camera.position.x,camera.position.z)+2.45;velocityY=0;onGround=true}}else{camera.position.y=H(camera.position.x,camera.position.z)+2.45;onGround=true}enemyClock+=dt;if(enemyClock>1.3){enemyClock=0;if(Math.random()<.58)damage(4+Math.random()*7)}actors.forEach((a,i)=>{if(!a.alive)return;a.phase+=dt*a.speed;let tx=a.origin.x+Math.sin(a.phase*.22+i)*5,tz=a.origin.z+Math.cos(a.phase*.2+i)*6;a.group.position.x+=(tx-a.group.position.x)*dt*.18;a.group.position.z+=(tz-a.group.position.z)*dt*.18;a.group.position.y=H(a.group.position.x,a.group.position.z);a.group.rotation.y=Math.sin(a.phase*.2)*.7});}
+renderer.render(scene,camera)}animate();document.querySelector('#loading').style.display='none';
 </script>
 </body>
